public class MetricsMemoryCache : IMemoryCache
{
    private readonly MemoryCache _inner;
    private readonly Counter<long> _hits;
    private readonly Counter<long> _misses;
    private readonly Histogram<double> _latency;

    public MetricsMemoryCache(IMemoryCache inner, ILogger<MetricsMemoryCache> logger)
    {
        _inner = inner as MemoryCache
            ?? throw new ArgumentException("Expected MemoryCache", nameof(inner));

        var meter = new Meter("MyApp.Cache", "1.0.0");
        _hits = meter.CreateCounter<long>("cache.hits");
        _misses = meter.CreateCounter<long>("cache.misses");
        _latency = meter.CreateHistogram<double>("cache.latency_ms");
    }

    public bool TryGetValue(object key, out object? value)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var result = _inner.TryGetValue(key, out value);
        sw.Stop();

        if (result) _hits.Increment();
        else _misses.Increment();

        _latency.Record(sw.Elapsed.TotalMilliseconds);
        return result;
    }

    // Delegate remaining IMemoryCache members to _inner...
}

public class RedisCacheProfiler
{
    private readonly IDatabase _db;
    private readonly IServer _server;

    public RedisProfiler(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
        _server = redis.GetServers().First();
    }

    public async Task<double> GetHitRatioAsync()
    {
        var info = await _server.InfoAsync(InfoSection.Statistics);
        var stats = info.FirstOrDefault(i => i.ContainsKey("keyspace_hits"));

        if (stats is null) return 0;

        var hits = long.Parse(stats["keyspace_hits"]);
        var misses = long.Parse(stats["keyspace_misses"]);
        var total = hits + misses;

        return total == 0 ? 0 : (double)hits / total;
    }

    public async Task LogSlowCommandsAsync(TimeSpan threshold)
    {
        var slowlog = await _server.SlowlogGetAsync(convertToMs: true);
        var slow = slowlog.Where(entry => entry.Duration >= threshold.TotalMilliseconds);
        foreach (var entry in slow)
        {
            Console.WriteLine($"Slow: {entry.Command} ({entry.Duration}ms) at {entry.TimeStamp}");
        }
    }
}
